  --radius-xl:  28px;

  --shadow-card: 0 2px 12px rgba(0,0,0,.45);
  --shadow-elevated: 0 8px 32px rgba(0,0,0,.55);

  --transition: 200ms ease;
  --max-width: 1280px;
  --gutter: clamp(16px, 4vw, 48px);
}

/* ============================================================
   Reset & Base
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; }
a   { color: inherit; text-decoration: none; }
ul  { list-style: none; }

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 16px;
  background: var(--color-accent);
  color: var(--color-white);
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 16px; }

/* Focus ring */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
  border-radius: 3px;
}

/* ============================================================
   Layout Utilities
   ============================================================ */
.container {
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: var(--gutter);
}

.section { padding-block: clamp(48px, 8vw, 96px); }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 36px;
  flex-wrap: wrap;
}

.section-title {
  font-size: clamp(1.375rem, 2.5vw, 1.875rem);
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.2;
}

.section-title span { color: var(--color-accent); }

.section-link {
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
  transition: gap var(--transition);
}
.section-link:hover { gap: 8px; }
.section-link svg { flex-shrink: 0; }

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ============================================================
   Buttons
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  line-height: 1;
}
.btn:active { transform: scale(.97); }

.btn-primary {
  background: var(--color-accent);
  color: var(--color-white);
}
.btn-primary:hover {
  background: var(--color-accent-hover);
  box-shadow: 0 4px 20px rgba(232,101,26,.4);
}

.btn-outline {
  background: transparent;
  color: var(--color-text);
  border: 1.5px solid var(--color-border);
}
.btn-outline:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}

.btn-ghost {
  background: rgba(255,255,255,.06);
  color: var(--color-text);
  border: 1px solid rgba(255,255,255,.08);
}
.btn-ghost:hover { background: rgba(255,255,255,.1); }

.btn-sm { padding: 8px 16px; font-size: .8125rem; border-radius: var(--radius-sm); }

/* ============================================================
   Tags / Badges
   ============================================================ */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: .6875rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 100px;
  line-height: 1;
}
.badge-accent  { background: var(--color-accent);       color: #fff; }
.badge-success { background: var(--color-success);      color: #001a0d; }
.badge-danger  { background: var(--color-danger);       color: #fff; }
.badge-muted   { background: var(--color-surface-2);    color: var(--color-text-muted); border: 1px solid var(--color-border); }

/* ============================================================
   Header / Navigation
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(15,15,18,.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  height: 68px;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 1.25rem;
  letter-spacing: -.03em;
  color: var(--color-white);
  flex-shrink: 0;
}
.logo-icon {
  width: 32px; height: 32px;
  background: var(--color-accent);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Nav */
.primary-nav { display: flex; align-items: center; gap: 4px; }
.primary-nav a {
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 500;
  color: var(--color-text-muted);
  transition: color var(--transition), background var(--transition);
}
.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
  color: var(--color-text);
  background: var(--color-surface);
}
.primary-nav a.nav-deals {
  color: var(--color-accent);
}

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.icon-btn {
  width: 40px; height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--color-text-muted);
  transition: color var(--transition), background var(--transition);
  position: relative;
}
.icon-btn:hover {
  color: var(--color-text);
  background: var(--color-surface);
}

.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 17px; height: 17px;
  background: var(--color-accent);
  color: #fff;
  font-size: .625rem;
  font-weight: 700;
  border-radius: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 4px;
}

/* Search bar */
.search-form {
  position: relative;
  flex: 1;
  max-width: 520px;
  margin-inline: auto;
}
.search-input {
  width: 100%;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  color: var(--color-text);
  font-family: inherit;
  font-size: .9rem;
  padding: 9px 16px 9px 42px;
  transition: border-color var(--transition), background var(--transition);
  appearance: none;
}
.search-input::placeholder { color: var(--color-text-subtle); }
.search-input:focus {
  outline: none;
  border-color: var(--color-accent);
  background: var(--color-surface-2);
}
.search-icon {
  position: absolute;
  left: 13px; top: 50%;
  transform: translateY(-50%);
  color: var(--color-text-subtle);
  pointer-events: none;
}

/* Mobile nav toggle */
.nav-toggle {
  display: none;
  color: var(--color-text-muted);
  padding: 8px;
}

/* ============================================================
   Announcement Bar
   ============================================================ */
.announcement-bar {
  background: var(--color-accent);
  color: #fff;
  text-align: center;
  font-size: .8125rem;
  font-weight: 600;
  padding: 9px var(--gutter);
  letter-spacing: .01em;
}
.announcement-bar a { text-decoration: underline; opacity: .85; }
.announcement-bar a:hover { opacity: 1; }

/* ============================================================
   Hero
   ============================================================ */
.hero {
  position: relative;
  min-height: clamp(460px, 60vh, 680px);
  display: flex;
  align-items: center;
  overflow: hidden;
  background: var(--color-surface);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 80% at 65% 50%, rgba(232,101,26,.18) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 20% 80%, rgba(96,60,200,.15) 0%, transparent 60%);
}

.hero-grid {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 48px;
  padding-block: 72px;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 20px;
}
.hero-eyebrow::before {
  content: '';
  width: 24px; height: 2px;
  background: currentColor;
  border-radius: 2px;
}

.hero-title {
  font-size: clamp(2.25rem, 5vw, 3.75rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.1;
  margin-bottom: 20px;
}
.hero-title em {
  font-style: normal;
  color: var(--color-accent);
}

.hero-subtitle {
  font-size: 1.0625rem;
  color: var(--color-text-muted);
  max-width: 440px;
  margin-bottom: 36px;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.hero-stats {
  display: flex;
  gap: 32px;
  margin-top: 48px;
  padding-top: 32px;
  border-top: 1px solid var(--color-border);
}
.hero-stat-value {
  font-size: 1.75rem;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--color-white);
  line-height: 1;
  margin-bottom: 4px;
}
.hero-stat-label {
  font-size: .8125rem;
  color: var(--color-text-muted);
  font-weight: 500;
}

/* Hero visual */
.hero-visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-product-card {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: 32px;
  text-align: center;
  width: 100%;
  max-width: 360px;
  margin-inline: auto;
  box-shadow: var(--shadow-elevated);
  position: relative;
  overflow: hidden;
}

.hero-product-card::before {
  content: '';
  position: absolute;
  top: -60px; right: -60px;
  width: 200px; height: 200px;
  background: radial-gradient(circle, rgba(232,101,26,.2) 0%, transparent 70%);
  pointer-events: none;
}

.hero-product-img {
  width: 220px; height: 220px;
  margin-inline: auto;
  margin-bottom: 24px;
  border-radius: var(--radius-lg);
  background: linear-gradient(135deg, #2a2a38 0%, #1a1a28 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
}

.hero-product-name {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 4px;
  color: var(--color-text);
}

.hero-product-meta {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-bottom: 20px;
}

.price-current {
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--color-white);
}
.price-original {
  font-size: .9rem;
  color: var(--color-text-subtle);
  text-decoration: line-through;
}
.price-save {
  font-size: .75rem;
  font-weight: 700;
  color: var(--color-success);
}

.floating-badge {
  position: absolute;
  top: 20px; left: 20px;
}

/* ============================================================
   Category Strip
   ============================================================ */
.category-strip {
  padding-block: 32px;
  border-bottom: 1px solid var(--color-border);
}

.category-list {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: 4px;
}
.category-list::-webkit-scrollbar { display: none; }

.category-pill {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 20px;
  border-radius: var(--radius-lg);
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  white-space: nowrap;
  transition: border-color var(--transition), background var(--transition), transform var(--transition);
  flex-shrink: 0;
  cursor: pointer;
}
.category-pill:hover {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
  transform: translateY(-2px);
}
.category-pill[aria-selected="true"] {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
  color: var(--color-accent);
}
.category-icon {
  font-size: 1.25rem;
  line-height: 1;
}
.category-name {
  font-size: .875rem;
  font-weight: 600;
}

/* ============================================================
   Product Cards
   ============================================================ */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
}

.product-card {
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
  position: relative;
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  border-color: rgba(232,101,26,.4);
  transform: translateY(-4px);
  box-shadow: var(--shadow-elevated);
}

.product-card-image {
  aspect-ratio: 1;
  background: var(--color-surface-2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  position: relative;
  overflow: hidden;
}

.product-card-badges {
  position: absolute;
  top: 12px;
  left: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.product-card-wishlist {
  position: absolute;
  top: 10px; right: 10px;
  width: 34px; height: 34px;
  background: rgba(15,15,18,.7);
  backdrop-filter: blur(8px);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  font-size: 1rem;
  transition: color var(--transition), background var(--transition);
  border: 1px solid var(--color-border);
}
.product-card-wishlist:hover {
  color: var(--color-danger);
  background: rgba(232,64,64,.15);
  border-color: var(--color-danger);
}
.product-card-wishlist[aria-pressed="true"] {
  color: var(--color-danger);
  background: rgba(232,64,64,.15);
  border-color: var(--color-danger);
}

.product-card-body {
  padding: 16px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.product-card-category {
  font-size: .75rem;
  font-weight: 600;
  color: var(--color-text-subtle);
  text-transform: uppercase;
  letter-spacing: .04em;
  margin-bottom: 4px;
}

.product-card-name {
  font-size: .9375rem;
  font-weight: 600;
  line-height: 1.35;
  margin-bottom: 8px;
  color: var(--color-text);
}

.product-card-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 12px;
}

.stars {
  display: flex;
  gap: 1px;
  color: #f5a623;
  font-size: .75rem;
}

.rating-count {
  font-size: .75rem;
  color: var(--color-text-muted);
}

.product-card-footer {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 12px;
  border-top: 1px solid var(--color-border);
}

.product-price {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.add-to-cart {
  width: 36px; height: 36px;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  transition: background var(--transition), transform var(--transition);
  flex-shrink: 0;
}
.add-to-cart:hover {
  background: var(--color-accent-hover);
  transform: scale(1.08);
}

/* ============================================================
   Deals Section
   ============================================================ */
.deals-section {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.deals-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 36px;
  flex-wrap: wrap;
}

.countdown-block {
  display: flex;
  align-items: center;
  gap: 8px;
}

.countdown-label {
  font-size: .8125rem;
  font-weight: 600;
  color: var(--color-text-muted);
  margin-right: 4px;
}

.countdown-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 6px 10px;
  min-width: 44px;
}

.countdown-value {
  font-size: 1.125rem;
  font-weight: 800;
  letter-spacing: -.02em;
  color: var(--color-accent);
  line-height: 1;
}

.countdown-tick {
  font-size: .625rem;
  color: var(--color-text-subtle);
  font-weight: 500;
  margin-top: 3px;
  text-transform: uppercase;
}

.countdown-sep {
  font-weight: 800;
  color: var(--color-text-subtle);
  font-size: 1.125rem;
  margin-bottom: 12px;
}

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}

.deal-card {
  background: var(--color-surface-2);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 16px;
  display: flex;
  gap: 16px;
  align-items: center;
  transition: border-color var(--transition), transform var(--transition);
  cursor: pointer;
}
.deal-card:hover {
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.deal-card-img {
  width: 72px; height: 72px;
  background: var(--color-surface);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.25rem;
  flex-shrink: 0;
}

.deal-card-body { flex: 1; min-width: 0; }

.deal-card-name {
  font-size: .875rem;
  font-weight: 600;
  margin-bottom: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.deal-card-price {
  display: flex;
  align-items: baseline;
  gap: 6px;
  margin-bottom: 8px;
}

.deal-progress {
  background: var(--color-border);
  border-radius: 100px;
  height: 4px;
  overflow: hidden;
}

.deal-progress-bar {
  height: 100%;
  background: var(--color-accent);
  border-radius: 100px;
  transition: width 1s ease;
}

.deal-stock-label {
  font-size: .6875rem;
  color: var(--color-text-muted);
  margin-top: 4px;
}

/* ============================================================
   Banner Strip
   ============================================================ */
.banner-strip {
  padding-block: 32px;
}

.banner-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 16px;
}

.banner-card {
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  position: relative;
  overflow: hidden;
  min-height: 160px;
  border: 1.5px solid var(--color-border);
  transition: transform var(--transition), box-shadow var(--transition);
}
.banner-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-elevated);
}

.banner-card-1 { background: linear-gradient(135deg, #1e1a38 0%, #2d1a4a 100%); }
.banner-card-2 { background: linear-gradient(135deg, #1a2e20 0%, #0f3320 100%); }
.banner-card-3 { background: linear-gradient(135deg, #2e1a1a 0%, #3d1010 100%); }

.banner-card-icon {
  font-size: 2.25rem;
  line-height: 1;
}

.banner-card-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-white);
  line-height: 1.3;
}

.banner-card-sub {
  font-size: .8125rem;
  color: var(--color-text-muted);
}

.banner-card-cta {
  margin-top: auto;
  font-size: .8125rem;
  font-weight: 700;
  color: var(--color-accent);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: gap var(--transition);
}
.banner-card:hover .banner-card-cta { gap: 10px; }

/* ============================================================
   Editorial Section
   ============================================================ */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 20px;
}

@media (max-width: 860px) {
  .editorial-grid { grid-template-columns: 1fr; }
}

.editorial-secondary {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.article-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  transition: border-color var(--transition), transform var(--transition);
}

.article-card:hover {
  border-color: rgba(232,101,26,.4);
  transform: translateY(-3px);
}

.article-card-featured {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.article-card-image {
  aspect-ratio: 16/9;
  background: var(--color-surface-2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  overflow: hidden;
  position: relative;
}

.article-card-featured .article-card-image { font-size: 6rem; }

.article-card-content {
  padding: 24px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.article-card-small .article-card-content { padding: 16px; }

.article-tag {
  display: inline-block;
  font-size: .6875rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 10px;
}

.article-card-title {
  font-size: 1.1875rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 10px;
  color: var(--color-text);
}

.article-card-small .article-card-title {
  font-size: .9375rem;
}

.article-card-excerpt {
  font-size: .875rem;
  color: var(--color-text-muted);
  line-height: 1.65;
  margin-bottom: 20px;
}

.article-card-meta {
  margin-top: auto;
  display: flex;
  align-items: center;
  gap: 12px;
}

.article-card-small {
  display: flex;
  flex-direction: row;
}

.article-card-small .article-card-image {
  width: 100px;
  aspect-ratio: 1;
  font-size: 2.5rem;
  flex-shrink: 0;
}

.article-card-small .article-card-content {
  padding: 14px 16px;
}

.article-meta-author {
  font-size: .75rem;
  color: var(--color-text-muted);
  font-weight: 500;
}

.article-meta-time {
  font-size: .75rem;
  color: var(--color-text-subtle);
  margin-left: auto;
}

/* ============================================================
   Newsletter
   ============================================================ */
.newsletter-section {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

@media (max-width: 640px) {
  .newsletter-inner { grid-template-columns: 1fr; }
}

.newsletter-heading {
  font-size: clamp(1.375rem, 3vw, 1.875rem);
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.25;
  margin-bottom: 8px;
}

.newsletter-sub {
  color: var(--color-text-muted);
  font-size: .9375rem;
  line-height: 1.65;
}

.newsletter-form {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.newsletter-input {
  flex: 1;
  min-width: 200px;
  background: var(--color-surface-2);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  color: var(--color-text);
  font-family: inherit;
  font-size: .9375rem;
  padding: 12px 18px;
  transition: border-color var(--transition);
}
.newsletter-input::placeholder { color: var(--color-text-subtle); }
.newsletter-input:focus {
  outline: none;
  border-color: var(--color-accent);
}

.newsletter-note {
  font-size: .75rem;
  color: var(--color-text-subtle);
  margin-top: 10px;
}

/* ============================================================
   Trust Bar
   ============================================================ */
.trust-bar {
  padding-block: 24px;
  border-bottom: 1px solid var(--color-border);
}

.trust-list {
  display: flex;
  justify-content: center;
  gap: clamp(20px, 5vw, 60px);
  flex-wrap: wrap;
}

.trust-item {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--color-text-muted);
  font-size: .875rem;
  font-weight: 500;
}

.trust-item-icon {
  font-size: 1.375rem;
  color: var(--color-accent);
}

/* ============================================================
   Footer
   ============================================================ */
.site-footer {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding-top: 60px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

@media (max-width: 860px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

.footer-brand-tagline {
  font-size: .875rem;
  color: var(--color-text-muted);
  line-height: 1.7;
  margin-top: 12px;
  margin-bottom: 20px;
}

.footer-social {
  display: flex;
  gap: 8px;
}

.social-btn {
  width: 36px; height: 36px;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .9rem;
  color: var(--color-text-muted);
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}
.social-btn:hover {
  color: var(--color-text);
  border-color: var(--color-accent);
  background: var(--color-accent-light);
}

.footer-col-title {
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--color-text-subtle);
  margin-bottom: 16px;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-links a {
  font-size: .875rem;
  color: var(--color-text-muted);
  transition: color var(--transition);
}
.footer-links a:hover { color: var(--color-text); }

.footer-bottom {
  border-top: 1px solid var(--color-border);
  padding-block: 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.footer-legal {
  font-size: .8125rem;
  color: var(--color-text-subtle);
}

.footer-legal-links {
  display: flex;
  gap: 20px;
}
.footer-legal-links a {
  font-size: .8125rem;
  color: var(--color-text-subtle);
  transition: color var(--transition);
}
.footer-legal-links a:hover { color: var(--color-text-muted); }

/* ============================================================
   Cart Drawer
   ============================================================ */
.cart-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.6);
  backdrop-filter: blur(4px);
  z-index: 200;
  opacity: 0;
  pointer-events: none;
  transition: opacity 300ms ease;
}
.cart-overlay.open { opacity: 1; pointer-events: all; }

.cart-drawer {
  position: fixed;
  top: 0; right: 0;
  width: 100%;
  max-width: 420px;
  height: 100%;
  background: var(--color-surface);
  border-left: 1px solid var(--color-border);
  z-index: 201;
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform 300ms cubic-bezier(.4,0,.2,1);
}
.cart-drawer.open { transform: translateX(0); }

.cart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  border-bottom: 1px solid var(--color-border);
}

.cart-title {
  font-size: 1.125rem;
  font-weight: 700;
}

.cart-body {
  flex: 1;
  overflow-y: auto;
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.cart-item {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--color-border);
}

.cart-item-img {
  width: 64px; height: 64px;
  background: var(--color-surface-2);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.75rem;
  flex-shrink: 0;
}

.cart-item-details { flex: 1; min-width: 0; }

.cart-item-name {
  font-size: .875rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.cart-item-variant {
  font-size: .75rem;
  color: var(--color-text-muted);
  margin-bottom: 10px;
}

.cart-item-controls {
  display: flex;
  align-items: center;
  gap: 10px;
}

.qty-btn {
  width: 26px; height: 26px;
  border-radius: 6px;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .875rem;
  font-weight: 700;
  color: var(--color-text);
  transition: border-color var(--transition);
}
.qty-btn:hover { border-color: var(--color-accent); }

.qty-value {
  font-size: .875rem;
  font-weight: 700;
  min-width: 20px;
  text-align: center;
}

.cart-item-price {
  font-size: .9375rem;
  font-weight: 700;
  color: var(--color-white);
  flex-shrink: 0;
}

.cart-footer {
  padding: 20px 24px;
  border-top: 1px solid var(--color-border);
}

.cart-subtotal {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.cart-subtotal-label {
  font-size: .9375rem;
  color: var(--color-text-muted);
}

.cart-subtotal-amount {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--color-white);
}

.cart-empty {
  text-align: center;
  padding: 48px 24px;
  color: var(--color-text-muted);
}

.cart-empty-icon { font-size: 3rem; margin-bottom: 12px; }

/* ============================================================
   Toast Notification
   ============================================================ */
.toast-container {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 300;
  display: flex;
  flex-direction: column;
  gap: 8px;
  pointer-events: none;
}

.toast {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 12px 20px;
  font-size: .875rem;
  font-weight: 500;
  color: var(--color-text);
  box-shadow: var(--shadow-elevated);
  display: flex;
  align-items: center;
  gap: 10px;
  white-space: nowrap;
  animation: toastIn 200ms ease, toastOut 200ms ease 2.8s forwards;
  pointer-events: all;
}

.toast-icon { font-size: 1rem; }

@keyframes toastIn {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes toastOut {
  from { opacity: 1; transform: translateY(0); }
  to   { opacity: 0; transform: translateY(8px); }
}

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width: 900px) {
  .hero-grid { grid-template-columns: 1fr; }
  .hero-visual { display: none; }
  .primary-nav { display: none; }
  .nav-toggle { display: flex; }
  .search-form { display: none; }

  .primary-nav.open {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: 68px;
    left: 0; right: 0;
    background: var(--color-surface);
    border-bottom: 1px solid var(--color-border);
    padding: 16px;
    gap: 4px;
    z-index: 99;
  }
  .primary-nav.open a {
    padding: 10px 14px;
    border-radius: var(--radius-sm);
  }
}

@media (max-width: 640px) {
  .deals-grid { grid-template-columns: 1fr; }
  .hero-stats { gap: 20px; }
  .header-inner { grid-template-columns: auto auto; }
}

/* ============================================================
   Scrollbar (Webkit)
   ============================================================ */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--color-bg); }
::-webkit-scrollbar-thumb { background: var(--color-border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--color-text-subtle); }
