   Design Tokens
   ============================================================ */
:root {
  --color-bg:           #0f0f12;
  --color-surface:      #1a1a22;
  --color-surface-2:    #23232f;
  --color-border:       #2e2e3d;
  --color-accent:       #e8651a;
  --color-accent-hover: #f07830;
  --color-accent-light: rgba(232,101,26,.12);
  --color-text:         #f0f0f5;
  --color-text-muted:   #8888a0;
  --color-text-subtle:  #555568;
  --color-success:      #22c97a;
  --color-danger:       #e84040;
  --color-white:        #ffffff;

  --font-sans: "Inter", system-ui, -apple-system, sans-serif;
  --font-display: "Inter", system-ui, sans-serif;

  --radius-sm:  6px;
  --radius-md:  12px;
  --radius-lg:  20px;
  --radius-xl:  28px;

  --shadow-card: 0 2px 12px rgba(0,0,0,.45);
  --shadow-elevated: 0 8px 32px rgba(0,0,0,.55);

  --transition: 200ms ease;
  --max-width: 1280px;
  --gutter: clamp(16px, 4vw, 48px);
}

/* ============================================================
   Reset & Base
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; }
a   { color: inherit; text-decoration: none; }
ul  { list-style: none; }

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 16px;
  background: var(--color-accent);
  color: var(--color-white);
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 16px; }

/* Focus ring */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
  border-radius: 3px;
}

/* ============================================================
   Layout Utilities
   ============================================================ */
.container {
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: var(--gutter);
}

.section { padding-block: clamp(48px, 8vw, 96px); }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 36px;
  flex-wrap: wrap;
}

.section-title {
  font-size: clamp(1.375rem, 2.5vw, 1.875rem);
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.2;
}

.section-title span { color: var(--color-accent); }

.section-link {
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
  transition: gap var(--transition);
}
.section-link:hover { gap: 8px; }
.section-link svg { flex-shrink: 0; }

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ============================================================
   Buttons
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  line-height: 1;
}
.btn:active { transform: scale(.97); }

.btn-primary {
  background: var(--color-accent);
  color: var(--color-white);
}
.btn-primary:hover {
  background: var(--color-accent-hover);
  box-shadow: 0 4px 20px rgba(232,101,26,.4);
}

.btn-outline {
  background: transparent;
  color: var(--color-text);
  border: 1.5px solid var(--color-border);
}
.btn-outline:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}

.btn-ghost {
  background: rgba(255,255,255,.06);
  color: var(--color-text);
  border: 1px solid rgba(255,255,255,.08);
}
.btn-ghost:hover { background: rgba(255,255,255,.1); }

.btn-sm { padding: 8px 16px; font-size: .8125rem; border-radius: var(--radius-sm); }

/* ============================================================
   Tags / Badges
   ============================================================ */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: .6875rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 100px;
  line-height: 1;
}
.badge-accent  { background: var(--color-accent);       color: #fff; }
.badge-success { background: var(--color-success);      color: #001a0d; }
.badge-danger  { background: var(--color-danger);       color: #fff; }
.badge-muted   { background: var(--color-surface-2);    color: var(--color-text-muted); border: 1px solid var(--color-border); }

/* ============================================================
   Header / Navigation
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(15,15,18,.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  height: 68px;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 1.25rem;
  letter-spacing: -.03em;
  color: var(--color-white);
  flex-shrink: 0;
}
.logo-icon {
  width: 32px; height: 32px;
  background: var(--color-accent);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Nav */
.primary-nav { display: flex; align-items: center; gap: 4px; }
.primary-nav a {
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 500;
  color: var(--color-text-muted);
  transition: color var(--transition), background var(--transition);
}
.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
  color: var(--color-text);
  background: var(--color-surface);
}
.primary-nav a.nav-deals {
  color: var(--color-accent);
}

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.icon-btn {
  width: 40px; height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--color-text-muted);
  transition: color var(--transition), background var(--transition);
  position: relative;
}
.icon-btn:hover {
  color: var(--color-text);
  background: var(--color-surface);
}

.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 17px; height: 17px;
  background: var(--color-accent);
  color: #fff;
  font-size: .625rem;
  font-weight: 700;
  border-radius: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 4px;
}

/* Search bar */
.search-form {
  position: relative;
  flex: 1;
  max-width: 520px;
  margin-inline: auto;
}
.search-input {
  width: 100%;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  color: var(--color-text);
  font-family: inherit;
  font-size: .9rem;
  padding: 9px 16px 9px 42px;
  transition: border-color var(--transition), background var(--transition);
  appearance: none;
}
.search-input::placeholder { color: var(--color-text-subtle); }
.search-input:focus {
  outline: none;
  border-color: var(--color-accent);
  background: var(--color-surface-2);
}
.search-icon {
  position: absolute;
  left: 13px; top: 50%;
  transform: translateY(-50%);
  color: var(--color-text-subtle);
  pointer-events: none;
}

/* Mobile nav toggle */
.nav-toggle {
  display: none;
  color: var(--color-text-muted);
  padding: 8px;
}

/* ============================================================
   Announcement Bar
   ============================================================ */
.announcement-bar {
  background: var(--color-accent);
  color: #fff;
  text-align: center;
  font-size: .8125rem;
  font-weight: 600;
  padding: 9px var(--gutter);
  letter-spacing: .01em;
}
.announcement-bar a { text-decoration: underline; opacity: .85; }
.announcement-bar a:hover { opacity: 1; }

/* ============================================================
   Hero
   ============================================================ */
.hero {
  position: relative;
  min-height: clamp(460px, 60vh, 680px);
  display: flex;
  align-items: center;
  overflow: hidden;
  background: var(--color-surface);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 80% at 65% 50%, rgba(232,101,26,.18) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 20% 80%, rgba(96,60,200,.15) 0%, transparent 60%);
}

.hero-grid {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 48px;
  padding-block: 72px;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 20px;
}
.hero-eyebrow::before {
  content: '';
  width: 24px; height: 2px;
  background: currentColor;
  border-radius: 2px;
}

.hero-title {
  font-size: clamp(2.25rem, 5vw, 3.75rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.1;
  margin-bottom: 20px;
}
.hero-title em {
  font-style: normal;
  color: var(--color-accent);
}

.hero-subtitle {
  font-size: 1.0625rem;
  color: var(--color-text-muted);
  max-width: 440px;
  margin-bottom: 36px;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.hero-stats {
  display: flex;
  gap: 32px;
  margin-top: 48px;
  padding-top: 32px;
  border-top: 1px solid var(--color-border);
}
.hero-stat-value {
  font-size: 1.75rem;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--color-white);
  line-height: 1;
  margin-bottom: 4px;
}
.hero-stat-label {
  font-size: .8125rem;
  color: var(--color-text-muted);
  font-weight: 500;
}

/* Hero visual */
.hero-visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-product-card {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: 32px;
  text-align: center;
  width: 100%;
  max-width: 360px;
  margin-inline: auto;
  box-shadow: var(--shadow-elevated);
  position: relative;
  overflow: hidden;
}

.hero-product-card::before {
  content: '';
  position: absolute;
  top: -60px; right: -60px;
  width: 200px; height: 200px;
  background: radial-gradient(circle, rgba(232,101,26,.2) 0%, transparent 70%);
  pointer-events: none;
}

.hero-product-img {
  width: 220px; height: 220px;
  margin-inline: auto;
  margin-bottom: 24px;
  border-radius: var(--radius-lg);
  background: linear-gradient(135deg, #2a2a38 0%, #1a1a28 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
}

.hero-product-name {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 4px;
  color: var(--color-text);
}

.hero-product-meta {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-bottom: 20px;
}

.price-current {
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--color-white);
}
.price-original {
  font-size: .9rem;
  color: var(--color-text-subtle);
  text-decoration: line-through;
}
.price-save {
  font-size: .75rem;
  font-weight: 700;
  color: var(--color-success);
}

.floating-badge {
  position: absolute;
  top: 20px; left: 20px;
}

/* ============================================================
   Category Strip
   ============================================================ */
.category-strip {
  padding-block: 32px;
  border-bottom: 1px solid var(--color-border);
}

.category-list {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: 4px;
}
.category-list::-webkit-scrollbar { display: none; }

.category-pill {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 20px;
  border-radius: var(--radius-lg);
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  white-space: nowrap;
  transition: border-color var(--transition), background var(--transition), transform var(--transition);
  flex-shrink: 0;
  cursor: pointer;
}
.category-pill:hover {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
  transform: translateY(-2px);
}
.category-pill[aria-selected="true"] {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
  color: var(--color-accent);
}
.category-icon {
  font-size: 1.25rem;
  line-height: 1;
}
.category-name {
  font-size: .875rem;
  font-weight: 600;
}

/* ============================================================
   Product Cards
   ============================================================ */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
}

.product-card {
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
  position: relative;
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  border-color: rgba(232,101,26,.4);
  transform: translateY(-4px);
  box-shadow: var(--shadow-elevated);
}

.product-card-image {
  aspect-ratio: 1;
