   ============================================================ */

// ── Data ─────────────────────────────────────────────────────
const PRODUCTS = [
  { id: 1, name: "Aether Wireless Headphones",  category: "Audio",    price: 249, originalPrice: 329, rating: 4.8, reviews: 2140, emoji: "🎧", badge: "Bestseller", badgeType: "badge-accent"  },
  { id: 2, name: "ProGrip Mechanical Keyboard", category: "Computing",price: 179, originalPrice: 229, rating: 4.6, reviews: 891,  emoji: "⌨️", badge: "New",        badgeType: "badge-success" },
  { id: 3, name: "StudioCam 4K Webcam",         category: "Video",    price: 139, originalPrice: 199, rating: 4.7, reviews: 674,  emoji: "📷", badge: "–23%",       badgeType: "badge-danger"  },
  { id: 4, name: "ErgoDesk Monitor Arm",        category: "Setup",    price:  89, originalPrice: 119, rating: 4.5, reviews: 1203, emoji: "🖥️", badge: null,         badgeType: null            },
  { id: 5, name: "Marble Desk Mat XL",          category: "Setup",    price:  49, originalPrice:  69, rating: 4.9, reviews: 3410, emoji: "🪨", badge: "Trending",   badgeType: "badge-muted"   },
  { id: 6, name: "USB-C Hub Pro 11-in-1",       category: "Computing",price:  79, originalPrice:  99, rating: 4.4, reviews: 562,  emoji: "🔌", badge: null,         badgeType: null            },
  { id: 7, name: "Kinetic Standing Mat",        category: "Wellness", price:  95, originalPrice: 130, rating: 4.6, reviews: 788,  emoji: "🟫", badge: "–27%",       badgeType: "badge-danger"  },
  { id: 8, name: "Flow Smart Water Bottle",     category: "Wellness", price:  38, originalPrice:  52, rating: 4.7, reviews: 2900, emoji: "💧", badge: "New",        badgeType: "badge-success" },
];

const DEALS = [
  { id: 1, name: "Aether Headphones", price: 199, originalPrice: 329, emoji: "🎧", stock: 72  },
  { id: 2, name: "Studio Webcam",     price: 109, originalPrice: 199, emoji: "📷", stock: 38  },
  { id: 3, name: "Marble Desk Mat",   price:  29, originalPrice:  69, emoji: "🪨", stock: 55  },
  { id: 4, name: "USB-C Hub Pro",     price:  55, originalPrice:  99, emoji: "🔌", stock: 21  },
];

const CATEGORIES = [
  { id: "all",       name: "All",        icon: "✦"  },
  { id: "audio",     name: "Audio",      icon: "🎧" },
  { id: "computing", name: "Computing",  icon: "⌨️" },
  { id: "setup",     name: "Setup",      icon: "🖥️" },
  { id: "wellness",  name: "Wellness",   icon: "💆" },
  { id: "video",     name: "Video",      icon: "📷" },
