const fmt = (n) => `$${n.toFixed(0)}`;
const pct = (orig, curr) => Math.round((1 - curr / orig) * 100);

function stars(rating) {
  return Array.from({ length: 5 }, (_, i) => {
    if (i < Math.floor(rating)) return "★";
    if (i < rating)             return "⯨";
    return "☆";
  }).join("");
