function addToCart(productId) {
  const product = PRODUCTS.find((p) => p.id === productId);
  if (!product) return;
  const existing = state.cart.find((i) => i.id === productId);
  if (existing) {
    existing.qty += 1;
  } else {
    state.cart.push({ ...product, qty: 1 });
  }
  renderCartDrawer();
  updateCartBadge();
  showToast("🛒", `<strong>${product.name}</strong> added to cart`);
}

function updateQty(productId, delta) {
  const item = state.cart.find((i) => i.id === productId);
  if (!item) return;
  item.qty = Math.max(0, item.qty + delta);
  if (item.qty === 0) {
    state.cart = state.cart.filter((i) => i.id !== productId);
  }
  renderCartDrawer();
  updateCartBadge();
}

function updateCartBadge() {
  const count = getCartCount();
  const badge = document.getElementById("cart-badge");
  badge.textContent = count;
  badge.hidden = count === 0;
  document.getElementById("cart-btn").setAttribute("aria-label", `Open cart, ${count} item${count !== 1 ? "s" : ""}`);
}

function openCart()  {
  document.getElementById("cart-overlay").classList.add("open");
  document.getElementById("cart-drawer").classList.add("open");
  document.getElementById("cart-drawer").focus();
  document.body.style.overflow = "hidden";
}

function closeCart() {
  document.getElementById("cart-overlay").classList.remove("open");
  document.getElementById("cart-drawer").classList.remove("open");
  document.body.style.overflow = "";
  document.getElementById("cart-btn").focus();
}

