];

const DEALS = [
  { id: 1, name: "Aether Headphones", price: 199, originalPrice: 329, emoji: "🎧", stock: 72  },
  { id: 2, name: "Studio Webcam",     price: 109, originalPrice: 199, emoji: "📷", stock: 38  },
  { id: 3, name: "Marble Desk Mat",   price:  29, originalPrice:  69, emoji: "🪨", stock: 55  },
  { id: 4, name: "USB-C Hub Pro",     price:  55, originalPrice:  99, emoji: "🔌", stock: 21  },
];

const CATEGORIES = [
  { id: "all",       name: "All",        icon: "✦"  },
  { id: "audio",     name: "Audio",      icon: "🎧" },
  { id: "computing", name: "Computing",  icon: "⌨️" },
  { id: "setup",     name: "Setup",      icon: "🖥️" },
  { id: "wellness",  name: "Wellness",   icon: "💆" },
  { id: "video",     name: "Video",      icon: "📷" },
];

// ── State ─────────────────────────────────────────────────────
const state = {
  cart: [],
  activeCategory: "all",
  wishlist: new Set(),
};

// ── Helpers ───────────────────────────────────────────────────
const fmt = (n) => `$${n.toFixed(0)}`;
const pct = (orig, curr) => Math.round((1 - curr / orig) * 100);

function stars(rating) {
  return Array.from({ length: 5 }, (_, i) => {
    if (i < Math.floor(rating)) return "★";
    if (i < rating)             return "⯨";
    return "☆";
  }).join("");
}

function getCartTotal() {
  return state.cart.reduce((sum, item) => sum + item.price * item.qty, 0);
}

function getCartCount() {
  return state.cart.reduce((sum, item) => sum + item.qty, 0);
}

// ── Toast ─────────────────────────────────────────────────────
function showToast(icon, message) {
  const container = document.getElementById("toast-container");
  const toast = document.createElement("div");
  toast.className = "toast";
  toast.setAttribute("role", "status");
  toast.setAttribute("aria-live", "polite");
  toast.innerHTML = `<span class="toast-icon" aria-hidden="true">${icon}</span>${message}`;
  container.appendChild(toast);
  setTimeout(() => toast.remove(), 3100);
}

// ── Cart ──────────────────────────────────────────────────────
function addToCart(productId) {
  const product = PRODUCTS.find((p) => p.id === productId);
  if (!product) return;
  const existing = state.cart.find((i) => i.id === productId);
  if (existing) {
    existing.qty += 1;
  } else {
    state.cart.push({ ...product, qty: 1 });
  }
  renderCartDrawer();
  updateCartBadge();
  showToast("🛒", `<strong>${product.name}</strong> added to cart`);
}

function updateQty(productId, delta) {
  const item = state.cart.find((i) => i.id === productId);
  if (!item) return;
  item.qty = Math.max(0, item.qty + delta);
  if (item.qty === 0) {
    state.cart = state.cart.filter((i) => i.id !== productId);
  }
  renderCartDrawer();
  updateCartBadge();
}

function updateCartBadge() {
  const count = getCartCount();
  const badge = document.getElementById("cart-badge");
  badge.textContent = count;
  badge.hidden = count === 0;
  document.getElementById("cart-btn").setAttribute("aria-label", `Open cart, ${count} item${count !== 1 ? "s" : ""}`);
}

function openCart()  {
  document.getElementById("cart-overlay").classList.add("open");
  document.getElementById("cart-drawer").classList.add("open");
  document.getElementById("cart-drawer").focus();
  document.body.style.overflow = "hidden";
}

function closeCart() {
  document.getElementById("cart-overlay").classList.remove("open");
  document.getElementById("cart-drawer").classList.remove("open");
  document.body.style.overflow = "";
  document.getElementById("cart-btn").focus();
}

function renderCartDrawer() {
  const body = document.getElementById("cart-body");
  const footer = document.getElementById("cart-footer");

  if (state.cart.length === 0) {
    body.innerHTML = `
      <div class="cart-empty" role="status">
        <div class="cart-empty-icon" aria-hidden="true">🛒</div>
        <p>Your cart is empty.</p>
        <p style="font-size:.8125rem;color:var(--color-text-subtle);margin-top:4px">Add some great products!</p>
      </div>`;
    footer.innerHTML = "";
    return;
  }

  body.innerHTML = state.cart.map((item) => `
    <div class="cart-item" data-id="${item.id}">
      <div class="cart-item-img" aria-hidden="true">${item.emoji}</div>
      <div class="cart-item-details">
        <p class="cart-item-name">${item.name}</p>
        <p class="cart-item-variant">${item.category}</p>
        <div class="cart-item-controls">
          <button class="qty-btn" aria-label="Decrease quantity of ${item.name}" onclick="updateQty(${item.id}, -1)">−</button>
          <span class="qty-value" aria-label="Quantity: ${item.qty}">${item.qty}</span>
          <button class="qty-btn" aria-label="Increase quantity of ${item.name}" onclick="updateQty(${item.id},  1)">+</button>
        </div>
      </div>
      <p class="cart-item-price">${fmt(item.price * item.qty)}</p>
    </div>
  `).join("");

  footer.innerHTML = `
    <div class="cart-subtotal">
      <span class="cart-subtotal-label">Subtotal</span>
      <span class="cart-subtotal-amount" aria-live="polite">${fmt(getCartTotal())}</span>
    </div>
    <button class="btn btn-primary" style="width:100%;justify-content:center" onclick="showToast('✅','Checkout coming soon!')">
      Checkout → ${fmt(getCartTotal())}
    </button>
    <p style="text-align:center;font-size:.75rem;color:var(--color-text-subtle);margin-top:10px">Free shipping on orders over $75</p>
  `;
}

// ── Wishlist ───────────────────────────────────────────────────
function toggleWishlist(productId, btn) {
  const product = PRODUCTS.find((p) => p.id === productId);
  if (state.wishlist.has(productId)) {
    state.wishlist.delete(productId);
    btn.setAttribute("aria-pressed", "false");
    btn.setAttribute("aria-label", `Add ${product?.name} to wishlist`);
    btn.innerHTML = "♡";
    showToast("💔", `Removed from wishlist`);
  } else {
    state.wishlist.add(productId);
    btn.setAttribute("aria-pressed", "true");
    btn.setAttribute("aria-label", `Remove ${product?.name} from wishlist`);
    btn.innerHTML = "♥";
    showToast("❤️", `<strong>${product?.name}</strong> saved to wishlist`);
  }
}

// ── Category filter ────────────────────────────────────────────
function filterCategory(catId) {
  state.activeCategory = catId;

  // Update pills
  document.querySelectorAll(".category-pill").forEach((pill) => {
    const active = pill.dataset.cat === catId;
    pill.setAttribute("aria-selected", String(active));
  });

  // Show/hide product cards
  document.querySelectorAll(".product-card[data-category]").forEach((card) => {
    const match = catId === "all" || card.dataset.category.toLowerCase() === catId;
    card.style.display = match ? "" : "none";
  });

  // Announce to screen readers
  const visible = document.querySelectorAll(".product-card[data-category]:not([style*='none'])").length;
  document.getElementById("product-count").textContent = `Showing ${visible} product${visible !== 1 ? "s" : ""}`;
}

// ── Countdown timer ────────────────────────────────────────────
function startCountdown() {
  const end = new Date();
  end.setHours(end.getHours() + 11, end.getMinutes() + 43, end.getSeconds() + 7);

  function tick() {
    const diff = Math.max(0, end - new Date());
    const h = Math.floor(diff / 3_600_000);
    const m = Math.floor((diff % 3_600_000) / 60_000);
    const s = Math.floor((diff % 60_000) / 1_000);

    const pad = (n) => String(n).padStart(2, "0");
    const hEl = document.getElementById("cd-hours");
    const mEl = document.getElementById("cd-minutes");
    const sEl = document.getElementById("cd-seconds");
    if (hEl) hEl.textContent = pad(h);
    if (mEl) mEl.textContent = pad(m);
    if (sEl) sEl.textContent = pad(s);
  }

  tick();
  setInterval(tick, 1_000);
}

// ── Mobile nav ────────────────────────────────────────────────
function toggleNav() {
  const nav   = document.getElementById("primary-nav");
  const btn   = document.getElementById("nav-toggle");
  const open  = nav.classList.toggle("open");
  btn.setAttribute("aria-expanded", String(open));
  btn.setAttribute("aria-label", open ? "Close navigation menu" : "Open navigation menu");
}

// ── Newsletter ─────────────────────────────────────────────────
function handleNewsletter(e) {
  e.preventDefault();
  const input = e.target.querySelector("input[type=email]");
  if (!input.value) return;
  showToast("📬", `You're subscribed! Welcome to NORD.`);
  input.value = "";
}

// ── Keyboard trap for cart drawer ─────────────────────────────
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") {
    const drawer = document.getElementById("cart-drawer");
    if (drawer.classList.contains("open")) closeCart();
    const nav = document.getElementById("primary-nav");
    if (nav.classList.contains("open")) toggleNav();
  }
});

// ── Init ──────────────────────────────────────────────────────
document.addEventListener("DOMContentLoaded", () => {
  renderCartDrawer();
  updateCartBadge();
  startCountdown();

  // Animate deal progress bars
  requestAnimationFrame(() => {
    document.querySelectorAll(".deal-progress-bar").forEach((bar) => {
      bar.style.width = bar.dataset.width;
    });
  });
});
