    showToast("💔", `Removed from wishlist`);
  } else {
    state.wishlist.add(productId);
    btn.setAttribute("aria-pressed", "true");
    btn.setAttribute("aria-label", `Remove ${product?.name} from wishlist`);
    btn.innerHTML = "♥";
    showToast("❤️", `<strong>${product?.name}</strong> saved to wishlist`);
  }
}

// ── Category filter ────────────────────────────────────────────
function filterCategory(catId) {
