document.addEventListener("DOMContentLoaded", () => {
  renderCartDrawer();
  updateCartBadge();
  startCountdown();

  // Animate deal progress bars
  requestAnimationFrame(() => {
    document.querySelectorAll(".deal-progress-bar").forEach((bar) => {
      bar.style.width = bar.dataset.width;
    });
  });
});
